import Form from '../models/Form.js';
import Response from '../models/Response.js';
import { parse } from 'json2csv';
import { v4 as uuidv4 } from 'uuid';

export const createForm = async (req, res) => {
  try {
    const { name, fields } = req.body;
    const shareId = uuidv4();
    const form = await Form.create({ name, fields, shareId });
    res.status(201).json(form);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create form' });
  }
};

export const getForm = async (req, res) => {
  try {
    const { shareId } = req.params;
    const form = await Form.findOne({ where: { shareId } });
    if (!form) return res.status(404).json({ error: 'Form not found' });
    res.json(form);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch form' });
  }
};

export const submitResponse = async (req, res) => {
  try {
    const { shareId } = req.params;
    const { answers } = req.body;
    const form = await Form.findOne({ where: { shareId } });
    if (!form) return res.status(404).json({ error: 'Form not found' });
    const response = await Response.create({ formId: form.id, answers });
    res.status(201).json(response);
  } catch (err) {
    res.status(500).json({ error: 'Failed to submit response' });
  }
};

export const getAnalytics = async (req, res) => {
  try {
    const { formId } = req.params;
    const totalResponses = await Response.count({ where: { formId } });
    res.json({ totalResponses });
  } catch (err) {
    res.status(500).json({ error: 'Analytics error' });
  }
};

export const exportCSV = async (req, res) => {
  try {
    const { formId } = req.params;
    const responses = await Response.findAll({ where: { formId } });
    const data = responses.map(r => r.answers);
    const csv = parse(data);
    res.header('Content-Type', 'text/csv');
    res.attachment('responses.csv');
    return res.send(csv);
  } catch (err) {
    res.status(500).json({ error: 'Failed to export CSV' });
  }
};

import { DataTypes } from 'sequelize';
import sequelize from '../utils/db.js';

const Form = sequelize.define('Form', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  name: { type: DataTypes.STRING, allowNull: false },
  fields: { type: DataTypes.JSONB, allowNull: false },
  shareId: { type: DataTypes.UUID, allowNull: false, unique: true }
});

export default Form;

import { DataTypes } from 'sequelize';
import sequelize from '../utils/db.js';
import Form from './Form.js';

const Response = sequelize.define('Response', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  formId: { type: DataTypes.INTEGER, allowNull: false, references: { model: Form, key: 'id' } },
  answers: { type: DataTypes.JSONB, allowNull: false }
});

export default Response;

import express from 'express';
import { createForm, getForm, submitResponse, getAnalytics, exportCSV } from '../controllers/formController.js';

const router = express.Router();

router.post('/', createForm);
router.get('/:shareId', getForm);
router.post('/:shareId/submit', submitResponse);
router.get('/:formId/analytics', getAnalytics);
router.get('/:formId/export', exportCSV);

export default router;

